#!/usr/bin/env node
/*
 * cdn-sync-artwork.mjs — push album SUPPORT images from the music drive to the CDN.
 *
 * The companion to cdn-sync-music.mjs, which says out loud that it touches audio
 * only. A supporting image is the wide 16:9 band above an album's song list,
 * generated by the WPF Studio and written beside the cover master:
 *
 *   <album>/artwork/<CODE>-support-<N>.webp
 *
 * 🔴 THE BUCKET KEY IS NOT THE PUBLIC URL, and getting that backwards is how the
 * old root-level sync pushed 23 GB into a prefix nothing serves. Measured against
 * a real object on 2026-08-19:
 *
 *   bucket key   music/albums/inspire/<artist>/<album>/artwork/EAIM1001EN.png
 *   public URL   https://cd.jubilujah.com/music/inspire/<artist>/<album>/artwork/EAIM1001EN.png   200
 *                https://cd.jubilujah.com/music/albums/inspire/…                                  404
 *
 * The edge strips the `albums/` segment; the bucket keeps it. So the upload key
 * is `music/` + the manifest's own album.path (which already begins `albums/`),
 * and the URL the site uses is that with `albums/` removed — exactly what
 * app/web/lib/cdn.ts musicUrl() does. Neither is guessed here: the path comes out
 * of catalog-manifest.json, which is what builds every URL the site plays.
 *
 * THE LOWEST-NUMBERED DRAFT WINS. The Studio writes several numbered drafts and
 * choosing between them is done by deleting the rest, so only the lowest survivor
 * is uploaded. Uploading them all would publish rejected work and leave the CDN
 * probe in scripts/gen-album-support.mjs resolving to a draft nobody picked.
 *
 * Usage:
 *   node tools/cdn-sync-artwork.mjs                # report only
 *   node tools/cdn-sync-artwork.mjs --apply        # upload
 *   node tools/cdn-sync-artwork.mjs --persona=eliana-inspire
 */
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const args = process.argv.slice(2);
const flag = (k) => args.includes(`--${k}`);
const opt = (k, d) => {
  const a = args.find((x) => x.startsWith(`--${k}=`));
  return a ? a.slice(k.length + 3) : d;
};

const REMOTE = opt('remote', 'jubilee-r2:jubileepraise-cdn');
const MANIFEST = opt('manifest', 'J:/jubileepraise.com/music/catalog-manifest.json');
const ONLY = opt('persona', '');
const APPLY = flag('apply');
const ROOTS = [
  'J:/jubileepraise.com/music',
  'J:/gopartygiggles.com/music',
  'J:/mytinytiggles.com/music',
];

const say = (s) => process.stdout.write(s + '\n');

// ── album code → the manifest's own path, so no key is ever constructed here ──
const manifest = JSON.parse(fs.readFileSync(MANIFEST, 'utf8'));
const pathByCode = new Map();
for (const c of manifest.categories || [])
  for (const a of c.artists || [])
    for (const al of a.albums || [])
      if (al.code && al.path) pathByCode.set(String(al.code).toUpperCase(), { path: al.path, artist: a.slug });

// ── the lowest-numbered surviving draft per album, off the drive ─────────────
const SUPPORT = new RegExp('^([A-Z0-9]+)-support-([0-9]+)[.]webp$', 'i');
const found = new Map();   // CODE -> { file, n, dir }

function walk(dir, depth) {
  if (depth > 4) return;
  let entries = [];
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
  for (const e of entries) {
    if (!e.isDirectory() || e.name.startsWith('_') || e.name.startsWith('.')) continue;
    const full = path.join(dir, e.name);
    if (e.name === 'artwork') {
      for (const f of fs.readdirSync(full)) {
        const m = SUPPORT.exec(f);
        if (!m) continue;
        const code = m[1].toUpperCase();
        const n = Number(m[2]);
        const prev = found.get(code);
        if (!prev || n < prev.n) found.set(code, { file: f, n, dir: full });
      }
    } else walk(full, depth + 1);
  }
}
for (const r of ROOTS) walk(r, 0);

// ── what is already published ────────────────────────────────────────────────
say(`Listing published support images in ${REMOTE}/music …`);
// Filtered to support images: the full music tree is tens of thousands of
// objects and every one of them but these is irrelevant here.
const listed = spawnSync('rclone', ['lsf', '-R', '--files-only', `${REMOTE}/music`,
  '--include', '*-support-*.webp', '--s3-no-check-bucket'], {
  encoding: "utf8", maxBuffer: 1 << 28,
});
if (listed.status !== 0) {
  say('✗ rclone could not list the bucket. Is the `jubilee-r2` remote configured?');
  say((listed.stderr || '').trim());
  process.exit(1);
}
const onCdn = new Set(listed.stdout.split('\n').map((s) => s.trim()).filter(Boolean));

// ── plan ─────────────────────────────────────────────────────────────────────
const upload = [], skip = [], orphan = [];
for (const [code, hit] of [...found].sort()) {
  const meta = pathByCode.get(code);
  // An image whose album is not in the manifest has no published path to go to,
  // and inventing one would put it somewhere the site never looks.
  if (!meta) { orphan.push(code); continue; }
  if (ONLY && meta.artist !== ONLY) continue;

  // Normalised, so it does not matter which manifest was read: the J: master
  // writes `inspire/<artist>/<album>` and the repo copy prefixes `albums/`.
  const norm = meta.path.replace(/^albums\//, "");
  const rel = `${norm}/artwork/${hit.file}`;              // relative to music/
  const src = path.join(hit.dir, hit.file);
  const row = { code, src, key: `music/${rel}`, rel, draft: hit.n };
  if (onCdn.has(rel)) skip.push(row); else upload.push(row);
}

say('');
say(`albums with a support image   ${found.size}`);
say(`already on the CDN            ${skip.length}`);
say(`to upload                     ${upload.length}`);
if (orphan.length) {
  say(`not in the manifest           ${orphan.length}  (no published path — skipped)`);
  say(`  ${orphan.slice(0, 8).join(', ')}${orphan.length > 8 ? ' …' : ''}`);
}
const rejected = [...found.values()].filter((h) => h.n > 1).length;
if (rejected) say(`(${rejected} album(s) publish a draft above 1 — earlier drafts were deleted, which is how a draft is chosen.)`);

if (!upload.length) { say('\nNothing to upload.'); process.exit(0); }
if (!APPLY) {
  say('');
  for (const r of upload.slice(0, 10)) say(`  ${r.code}  ->  ${r.key}`);
  if (upload.length > 10) say(`  … and ${upload.length - 10} more`);
  say(`\nReport only. Re-run with --apply to upload ${upload.length} file(s).`);
  process.exit(0);
}

// ── upload ───────────────────────────────────────────────────────────────────
say('');
let ok = 0, bad = 0;
for (const r of upload) {
  const dest = `${REMOTE}/${path.posix.dirname(r.key)}/`;
  // --s3-no-check-bucket: the R2 token is scoped to objects and cannot
  // CreateBucket, which rclone otherwise attempts before every copy.
  const res = spawnSync('rclone', ['copy', r.src, dest, '--no-traverse', '--s3-no-check-bucket'], { encoding: 'utf8' });
  if (res.status === 0) { ok++; if (ok % 25 === 0) say(`  … ${ok}/${upload.length}`); }
  else { bad++; say(`  ✗ ${r.code}: ${(res.stderr || '').trim().split('\n').pop()}`); }
}
say('');
say(`uploaded ${ok}, failed ${bad}`);
say('Now re-run: node app/web/scripts/gen-album-support.mjs   (CDN probe, so the site indexes them)');
